-- Grama One centres, Karnataka. Source: Open City 'Grama One centres in Karnataka and Bengaluru' (ka_grama_one_locations.kml, synced 2023).
-- Operator mobile numbers are deliberately not loaded. Two rows with coordinates outside Karnataka were dropped.
CREATE TABLE portal.gramaone_centre (
    id             integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    opr_code       text NOT NULL,
    district       text NOT NULL,
    taluk          text NOT NULL,
    gram_panchayat text NOT NULL,
    village        text NOT NULL,
    latitude       double precision NOT NULL,
    longitude      double precision NOT NULL
);
CREATE INDEX ix_gramaone_centre_district ON portal.gramaone_centre (district);

